// Stats
export const CATEGORIES = Array.from(new Set(MIDI_DATA.map(d => d.categorie)));
export const TOTAL = MIDI_DATA.length;

export const STATS_BY_CATEGORY = CATEGORIES.map(cat => ({
  categorie: cat,
  total: MIDI_DATA.filter(d => d.categorie === cat).length,
  entree_sortie: MIDI_DATA.filter(d => d.categorie === cat && d.type === "Entrée/Sortie").length,
  entree: MIDI_DATA.filter(d => d.categorie === cat && d.type === "Entrée").length,
  sortie: MIDI_DATA.filter(d => d.categorie === cat && d.type === "Sortie").length,
}));

